KG42.register("edges-155f6a4d0fcdce53ff8c604c",{"id":"S-29b823b974f90280","source":"KG31-fc19e7c39ea9de54","type":"links","target":"KG40-e988fed52eadab03","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["19-two_stage_battery_sharing"],"assertions":[{"id":"19-two_stage_battery_sharing::v141-c-R002::E::v141-c-R002-E001","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R002","rule_ref":"19-two_stage_battery_sharing::v141-c-R002","record":{"edge_id":"v141-c-R002-E001","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e002"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R002-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-fc19e7c39ea9de54","target":"KG40-e988fed52eadab03","source_occurrence_id":"19-two_stage_battery_sharing::v141-c-R002::V::coordination.local_operator","target_occurrence_id":"19-two_stage_battery_sharing::v141-c-R002::V::execution.energy_trade","source_unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","target_unit_id":"19-two_stage_battery_sharing::v141-a-M01::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Neighborhood energy exchanges within the P2P sharing community. | P2P energy sharing between customers within the community Microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e007"]},"active":true,"source_signature":"e9d851421597f22c7da9142ea7c3be2341553de5fd4c81a0aea5069085b9054e","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community. Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","target_definition":"The ESC, acting as the local market operator, coordinates P2P energy sharing between community customers. Scope: P2P energy sharing between customers within the community Microgrid. P2P sharing permits local buying and selling of energy, including PV sharing among prosumers and trades of surplus PV power with consumers without PV systems. Scope: Neighborhood energy exchanges within the P2P sharing community.","constraints":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The ESC, acting as the local market operator, coordinates P2P energy sharing between community customers. Scope: P2P energy sharing between customers within the community Microgrid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e002"]}],"evidence":[{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Neighborhood energy exchanges within the P2P sharing community. | P2P energy sharing between customers within the community Microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e007"]},"source_record":{"edge_id":"v141-c-R002-E001","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e002"]},"paper_scope_note":"Electricity bill settlement directly depends on the post-metering price; the revenue improvement is a conditional statement and sensitivity case in the paper, not a general proposition independently verified in this work."}}],"assertion_ids":["19-two_stage_battery_sharing::v141-c-R002::E::v141-c-R002-E001"]});
